// Nouvelle notification locale ciblee : "ta serie va sauter" - envoyee
// uniquement quand le joueur a une serie en cours (currentStreak > 0) et
// n'a pas encore joue aujourd'hui, annulee des qu'il joue. Reutilise
// l'infra de notif locale deja existante (rappel generique 19h) - pas de
// backend, respecte le meme interrupteur "notifications" des Reglages.
// Programmee pour 20h, ou 23h30 en secours si l'app est ouverte apres
// 20h (sinon les gens qui ouvrent l'app tard dans la soiree n'auraient
// jamais de rappel du tout).
// Run from strikr-app/: node patch-streak-risk-notif.js
const fs = require('fs');
const path = require('path');

function write(rel, content) {
  const full = path.join(process.cwd(), rel);
  fs.writeFileSync(full, content);
  console.log('WROTE', rel);
}

write("src/lib/notifications.ts", "// Local daily reminder notification (no backend/push token involved — Expo\n// Go on recent SDKs no longer supports remote push, so this sticks to\n// device-scheduled local notifications, which work fine for a \"come back\n// and play\" nudge and need no server round-trip).\n//\n// Remote push (registerPushToken below) is separate: it only works in a\n// standalone/EAS build (not Expo Go), and is used for friend duel-invite\n// notifications sent from the backend via Expo's push API.\nimport { Platform } from 'react-native';\nimport Constants from 'expo-constants';\nimport * as Device from 'expo-device';\nimport * as Notifications from 'expo-notifications';\nimport { supabase } from './supabase';\n\nconst DAILY_REMINDER_ID = 'strikr-daily-reminder';\nconst REMINDER_HOUR = 19;\n\nNotifications.setNotificationHandler({\n  handleNotification: async () => ({\n    shouldShowBanner: true,\n    shouldShowList: true,\n    shouldPlaySound: true,\n    shouldSetBadge: false,\n  }),\n});\n\nexport async function requestNotificationPermission(): Promise<boolean> {\n  if (Platform.OS === 'web') return false;\n  const existing = await Notifications.getPermissionsAsync();\n  if (existing.granted) return true;\n  const requested = await Notifications.requestPermissionsAsync();\n  return requested.granted;\n}\n\nexport async function scheduleDailyReminder(title: string, body: string): Promise<void> {\n  if (Platform.OS === 'web') return;\n  await Notifications.cancelScheduledNotificationAsync(DAILY_REMINDER_ID).catch(() => {});\n  await Notifications.scheduleNotificationAsync({\n    identifier: DAILY_REMINDER_ID,\n    content: { title, body, sound: true },\n    trigger: {\n      type: Notifications.SchedulableTriggerInputTypes.DAILY,\n      hour: REMINDER_HOUR,\n      minute: 0,\n    },\n  });\n}\n\nexport async function cancelDailyReminder(): Promise<void> {\n  if (Platform.OS === 'web') return;\n  await Notifications.cancelScheduledNotificationAsync(DAILY_REMINDER_ID).catch(() => {});\n}\n\n// One-off (not recurring) nudge for tonight only, re-evaluated by the\n// caller (see settings.tsx) every time stats change: scheduled when the\n// player has a win streak going but hasn't played today, cancelled the\n// moment they do. This only runs when the app happens to be open (no\n// background timer), so a fixed 20:00 target would silently skip anyone\n// who opens the app later than that with hours still left before\n// midnight — falls back to a later \"last call\" time instead, and only\n// gives up once even that has passed.\nconst STREAK_RISK_ID = 'strikr-streak-risk';\nconst STREAK_RISK_HOUR = 20;\nconst STREAK_RISK_LAST_CALL_HOUR = 23;\nconst STREAK_RISK_LAST_CALL_MINUTE = 30;\n\nexport async function scheduleStreakRiskReminder(title: string, body: string): Promise<void> {\n  if (Platform.OS === 'web') return;\n  await Notifications.cancelScheduledNotificationAsync(STREAK_RISK_ID).catch(() => {});\n  let target = new Date();\n  target.setHours(STREAK_RISK_HOUR, 0, 0, 0);\n  if (target.getTime() <= Date.now()) {\n    target = new Date();\n    target.setHours(STREAK_RISK_LAST_CALL_HOUR, STREAK_RISK_LAST_CALL_MINUTE, 0, 0);\n  }\n  if (target.getTime() <= Date.now()) return;\n  await Notifications.scheduleNotificationAsync({\n    identifier: STREAK_RISK_ID,\n    content: { title, body, sound: true },\n    trigger: { type: Notifications.SchedulableTriggerInputTypes.DATE, date: target },\n  });\n}\n\nexport async function cancelStreakRiskReminder(): Promise<void> {\n  if (Platform.OS === 'web') return;\n  await Notifications.cancelScheduledNotificationAsync(STREAK_RISK_ID).catch(() => {});\n}\n\n// Gets (or lazily creates) this device's Expo push token and saves it on the\n// signed-in user's profile so the backend can push friend duel-invite\n// notifications to it. Silently no-ops on web, in Expo Go, or on a\n// simulator, where no real push token exists.\nexport async function registerPushToken(userId: string): Promise<void> {\n  if (Platform.OS === 'web' || !Device.isDevice) return;\n  const projectId = Constants.expoConfig?.extra?.eas?.projectId;\n  if (!projectId) return;\n  try {\n    const { data: token } = await Notifications.getExpoPushTokenAsync({ projectId });\n    if (token) await supabase.from('profiles').update({ push_token: token }).eq('id', userId);\n  } catch {\n    // no-op: push token isn't available in every environment (e.g. Expo Go)\n  }\n}\n\nexport async function clearPushToken(userId: string): Promise<void> {\n  try {\n    await supabase.from('profiles').update({ push_token: null }).eq('id', userId);\n  } catch {\n    // no-op: best-effort cleanup, e.g. on sign-out\n  }\n}\n");
write("src/state/settings.tsx", "// Sound/haptics/notifications preferences, persisted locally. Exposes plain\n// getter functions too (getSoundEnabled/getHapticsEnabled) so non-component\n// code like src/lib/fx.ts can check the current preference synchronously\n// without needing a React context.\nimport React, { createContext, useCallback, useContext, useEffect, useRef, useState } from 'react';\nimport AsyncStorage from '@react-native-async-storage/async-storage';\nimport {\n  requestNotificationPermission,\n  scheduleDailyReminder,\n  cancelDailyReminder,\n  registerPushToken,\n  scheduleStreakRiskReminder,\n  cancelStreakRiskReminder,\n} from '../lib/notifications';\nimport { useI18n } from '../i18n/i18n';\nimport { useAuth } from './auth';\nimport { useStats } from './stats';\n\nfunction todayStr(): string {\n  return new Date().toISOString().slice(0, 10);\n}\n\nconst KEY = 'strikr_settings_v1';\n\ninterface SettingsData {\n  soundEnabled: boolean;\n  hapticsEnabled: boolean;\n  notificationsEnabled: boolean;\n}\n\nconst DEFAULT_SETTINGS: SettingsData = {\n  soundEnabled: true,\n  hapticsEnabled: true,\n  notificationsEnabled: true,\n};\n\nlet currentSettings: SettingsData = { ...DEFAULT_SETTINGS };\nexport function getSoundEnabled(): boolean {\n  return currentSettings.soundEnabled;\n}\nexport function getHapticsEnabled(): boolean {\n  return currentSettings.hapticsEnabled;\n}\n\ninterface SettingsContextValue {\n  settings: SettingsData;\n  setSoundEnabled: (v: boolean) => void;\n  setHapticsEnabled: (v: boolean) => void;\n  setNotificationsEnabled: (v: boolean) => void;\n}\n\nconst SettingsContext = createContext<SettingsContextValue | null>(null);\n\nexport function SettingsProvider({ children }: { children: React.ReactNode }) {\n  const { t } = useI18n();\n  const { user } = useAuth();\n  const [settings, setSettings] = useState<SettingsData>(DEFAULT_SETTINGS);\n  const [loaded, setLoaded] = useState(false);\n\n  useEffect(() => {\n    AsyncStorage.getItem(KEY)\n      .then((raw) => {\n        if (!raw) return;\n        try {\n          const parsed = { ...DEFAULT_SETTINGS, ...JSON.parse(raw) };\n          currentSettings = parsed;\n          setSettings(parsed);\n        } catch {\n          // ignore corrupt storage, keep defaults\n        }\n      })\n      .finally(() => setLoaded(true));\n  }, []);\n\n  // Keep the OS-scheduled daily reminder in sync with the persisted\n  // preference once the user is signed in (idempotent: schedule/cancel are\n  // safe to call repeatedly), so a fresh install with the default-on toggle\n  // actually gets the reminder without having to flip it off/on once. Gated\n  // on `user` so the OS permission prompt never appears before login.\n  useEffect(() => {\n    if (!loaded || !user) return;\n    if (settings.notificationsEnabled) {\n      requestNotificationPermission().then((granted) => {\n        if (granted) {\n          scheduleDailyReminder(t('notif_reminder_title'), t('notif_reminder_body'));\n          registerPushToken(user.id);\n        }\n      });\n    } else {\n      cancelDailyReminder();\n    }\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [loaded, user]);\n\n  // Re-evaluated on every stats change (i.e. after every win, and once on\n  // load): a one-off \"tonight only\" nudge, scheduled only while there's an\n  // actual streak on the line the player hasn't extended today yet, and\n  // cancelled the instant they play — never a nag with nothing to lose.\n  const { stats, ready: statsReady } = useStats();\n  useEffect(() => {\n    if (!loaded || !user || !statsReady) return;\n    const atRisk = settings.notificationsEnabled && stats.currentStreak > 0 && stats.lastPlayedDate !== todayStr();\n    if (atRisk) {\n      scheduleStreakRiskReminder(t('notif_streak_risk_title'), t('notif_streak_risk_body'));\n    } else {\n      cancelStreakRiskReminder();\n    }\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [loaded, user, statsReady, settings.notificationsEnabled, stats.currentStreak, stats.lastPlayedDate]);\n\n  const update = useCallback((patch: Partial<SettingsData>) => {\n    setSettings((prev) => {\n      const next = { ...prev, ...patch };\n      currentSettings = next;\n      AsyncStorage.setItem(KEY, JSON.stringify(next)).catch(() => {});\n      return next;\n    });\n  }, []);\n\n  const setSoundEnabled = useCallback((v: boolean) => update({ soundEnabled: v }), [update]);\n  const setHapticsEnabled = useCallback((v: boolean) => update({ hapticsEnabled: v }), [update]);\n  const setNotificationsEnabled = useCallback((v: boolean) => update({ notificationsEnabled: v }), [update]);\n\n  return (\n    <SettingsContext.Provider value={{ settings, setSoundEnabled, setHapticsEnabled, setNotificationsEnabled }}>\n      {children}\n    </SettingsContext.Provider>\n  );\n}\n\nexport function useSettings() {\n  const ctx = useContext(SettingsContext);\n  if (!ctx) throw new Error('useSettings must be used within SettingsProvider');\n  return ctx;\n}\n");
